using ManufacturerERP.Data;
using ManufacturerERP.Models;
using ManufacturerERP.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ManufacturerERP.Controllers;
[Authorize]
public class MastersController(ApplicationDbContext db, IAuditService audit) : Controller
{
    private static readonly string[] Types = ["units", "warehouses", "products", "customers", "suppliers"];
    private bool Valid(string type) => Types.Contains(type.ToLower());
    private IQueryable<MasterRecord> Query(string type) => type.ToLower() switch {
        "units" => db.Units, "warehouses" => db.Warehouses, "products" => db.Products.Include(x => x.Unit), "customers" => db.Customers, "suppliers" => db.Suppliers, _ => throw new ArgumentException() };
    private string Title(string type) => type[..1].ToUpper() + type[1..];

    [HttpGet("Masters/{type}")] public async Task<IActionResult> Index(string type, string? search, bool? active)
    { if (!Valid(type)) return NotFound(); var rows = await Query(type).OrderByDescending(x => x.IsActive).ThenBy(x => x.Id).ToListAsync(); if(active.HasValue) rows=rows.Where(x=>x.IsActive==active).ToList(); if(!string.IsNullOrWhiteSpace(search)) rows=rows.Where(x=>Name(x).Contains(search,StringComparison.OrdinalIgnoreCase) || (x is Unit u && u.ShortCode.Contains(search,StringComparison.OrdinalIgnoreCase)) || (x is not Unit && (x switch { Warehouse w=>w.Code, Product p=>p.Code, Party p=>p.Code, _=>"" }).Contains(search,StringComparison.OrdinalIgnoreCase))).ToList(); ViewBag.Type = type; ViewBag.Title = Title(type); return View(rows); }

    [Authorize(Roles = "Admin,Manager,Storekeeper,Sales,Purchase")]
    [HttpGet("Masters/{type}/create")] public async Task<IActionResult> Create(string type) { if (!Valid(type)) return NotFound(); ViewBag.Type=type; ViewBag.Units=await db.Units.Where(x=>x.IsActive).OrderBy(x=>x.Name).ToListAsync(); return View("Edit", New(type)); }
    [HttpPost("Masters/{type}/create"), ValidateAntiForgeryToken] public async Task<IActionResult> Create(string type, IFormCollection form) { if (!Valid(type)) return NotFound(); var item=New(type); Bind(item,form); if (!TryValidateModel(item) || await Duplicate(type,item)) { ModelState.AddModelError("", "Please correct validation errors. Codes must be unique."); ViewBag.Type=type; ViewBag.Units=await db.Units.Where(x=>x.IsActive).ToListAsync(); return View("Edit",item); } db.Add(item); await db.SaveChangesAsync(); await audit.LogAsync(User,"Create",item.GetType().Name,item.Id,$"Created {Name(item)}"); TempData["Success"]=$"{Title(type)} created."; return RedirectToAction(nameof(Index),new{type}); }
    [HttpGet("Masters/{type}/{id:int}/edit")] public async Task<IActionResult> Edit(string type,int id) { if(!Valid(type))return NotFound(); var item=await Query(type).FirstOrDefaultAsync(x=>x.Id==id); if(item is null)return NotFound(); ViewBag.Type=type;ViewBag.Units=await db.Units.Where(x=>x.IsActive).ToListAsync(); return View(item); }
    [HttpPost("Masters/{type}/{id:int}/edit"), ValidateAntiForgeryToken] public async Task<IActionResult> Edit(string type,int id,IFormCollection form) { var item=Valid(type)?await Query(type).FirstOrDefaultAsync(x=>x.Id==id):null; if(item is null)return NotFound(); Bind(item,form); if(!TryValidateModel(item)||await Duplicate(type,item)) { ModelState.AddModelError("","Please correct validation errors. Codes must be unique.");ViewBag.Type=type;ViewBag.Units=await db.Units.Where(x=>x.IsActive).ToListAsync();return View(item); } item.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();await audit.LogAsync(User,"Update",item.GetType().Name,item.Id,$"Updated {Name(item)}");TempData["Success"]="Changes saved.";return RedirectToAction(nameof(Index),new{type}); }
    [HttpPost("Masters/{type}/{id:int}/toggle"), ValidateAntiForgeryToken] public async Task<IActionResult> Toggle(string type,int id) { var item=Valid(type)?await Query(type).FirstOrDefaultAsync(x=>x.Id==id):null;if(item is null)return NotFound();item.IsActive=!item.IsActive;item.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();await audit.LogAsync(User,item.IsActive?"Activate":"Deactivate",item.GetType().Name,id,$"{Name(item)} status changed");TempData["Success"]=$"Record {(item.IsActive?"activated":"deactivated")}.";return RedirectToAction(nameof(Index),new{type}); }
    private MasterRecord New(string type) => type.ToLower() switch { "units"=>new Unit(),"warehouses"=>new Warehouse(),"products"=>new Product(),"customers"=>new Customer(),"suppliers"=>new Supplier(),_=>throw new ArgumentException()};
    private static string Name(MasterRecord x) => x switch { Unit a=>a.Name, Warehouse a=>a.Name, Product a=>a.Name, Party a=>a.Name, _=>"record"};
    private async Task<bool> Duplicate(string type,MasterRecord item) { var code=item switch {Unit x=>x.ShortCode,Warehouse x=>x.Code,Product x=>x.Code,Party x=>x.Code,_=>""}; return type.ToLower() switch {"units"=>await db.Units.AnyAsync(x=>x.ShortCode==code&&x.Id!=item.Id),"warehouses"=>await db.Warehouses.AnyAsync(x=>x.Code==code&&x.Id!=item.Id),"products"=>await db.Products.AnyAsync(x=>x.Code==code&&x.Id!=item.Id),"customers"=>await db.Customers.AnyAsync(x=>x.Code==code&&x.Id!=item.Id),_=>await db.Suppliers.AnyAsync(x=>x.Code==code&&x.Id!=item.Id)}; }
    private static void Bind(MasterRecord x,IFormCollection f) { string S(string k)=>f[k].ToString(); bool B(string k)=>f[k].Any(value=>string.Equals(value,"true",StringComparison.OrdinalIgnoreCase)); if(x is Unit unit){unit.Name=S("Name");unit.ShortCode=S("ShortCode");unit.Description=S("Description");unit.IsActive=B("IsActive");} else if(x is Warehouse warehouse){warehouse.Name=S("Name");warehouse.Code=S("Code");warehouse.Address=S("Address");warehouse.City=S("City");warehouse.Description=S("Description");warehouse.IsActive=B("IsActive");} else if(x is Product product){product.Name=S("Name");product.Code=S("Code");product.Description=S("Description");product.UnitId=int.TryParse(S("UnitId"),out var n)?n:0;product.ItemType=Enum.TryParse<ItemType>(S("ItemType"),out var t)?t:ItemType.Other;product.PurchasePrice=decimal.TryParse(S("PurchasePrice"),out var p)?p:0;product.SalePrice=decimal.TryParse(S("SalePrice"),out var q)?q:0;product.MinimumStockLevel=decimal.TryParse(S("MinimumStockLevel"),out var m)?m:0;product.IsActive=B("IsActive");} else if(x is Party party){party.Name=S("Name");party.Code=S("Code");party.ContactPerson=S("ContactPerson");party.Phone=S("Phone");party.Email=S("Email");party.Address=S("Address");party.City=S("City");party.Province=S("Province");party.NTN=S("NTN");party.STRN=S("STRN");party.PaymentTerms=int.TryParse(S("PaymentTerms"),out var n)?n:0;party.Notes=S("Notes");party.IsActive=B("IsActive");if(party is Customer c)c.CreditLimit=decimal.TryParse(S("CreditLimit"),out var d)?d:0;} }
}
